example_solution:
library(dplyr)

does_stack_include_card <- function(stack, card) {
  card %in% stack
}

get_card_position <- function(stack, card) {
  if_else(does_stack_include_card(stack, card), which(stack == card)[1], -1)
}

is_each_card_even <- function(stack) {
  all(stack %% 2 == 0)
}

does_stack_include_odd_card <- function(stack) {
  !is_each_card_even(stack)
}

get_first_odd_card <- function(stack) {
  if_else(does_stack_include_odd_card(stack), stack[stack %% 2 != 0][1], -1)
}

get_first_even_card_position <- function(stack) {
  if_else(any(stack %% 2 == 0), which(stack %% 2 == 0)[1], -1)
}

test_code:
source("./elyses-analytic-enchantments.R")
library(testthat)

# does_stack_include_card

test_that("1. when it is the first card", {
  stack <- c(1, 2, 3)
  card <- 1
  expect_equal(does_stack_include_card(stack, card), TRUE)
})

test_that("1. when there is a card found", {
  stack <- c(1, 2, 3)
  card <- 4
  expect_equal(does_stack_include_card(stack, card), FALSE)
})

# get_card_position

test_that("2. when it is the first card", {
  stack <- c(1, 2, 3)
  card <- 1
  expect_equal(get_card_position(stack, card), 1)
})

test_that("2. when the card is not found", {
  stack <- c(1, 2, 3)
  card <- 4
  expect_equal(get_card_position(stack, card), -1)
})

# is_each_card_even

test_that("3. when all cards are even", {
  stack <- c(2, 4, 6)
  expect_equal(is_each_card_even(stack), TRUE)
})

test_that("3. when any card is odd", {
  stack <- c(2, 5, 6)
  expect_equal(is_each_card_even(stack), FALSE)
})

# does_stack_include_odd_card

test_that("4. should be true if odd number card is found", {
  stack <- c(2, 5, 6)
  expect_equal(does_stack_include_odd_card(stack), TRUE)
})

test_that("4. should be false if no odd number card is found", {
  stack <- c(2, 4, 6)
  expect_equal(does_stack_include_odd_card(stack), FALSE)
})

# get_first_odd_card

test_that("5. should return the first odd card found", {
  stack <- c(2, 4, 1, 3)
  expect_equal(get_first_odd_card(stack), 1)
})

test_that("5. should return -1 if odd card is not found", {
  stack <- c(4, 2, 6)
  expect_equal(get_first_odd_card(stack), -1)
})

# get_first_even_card_position

test_that("6. should return position of first even card", {
  stack <- c(2, 4, 1, 3)
  expect_equal(get_first_even_card_position(stack), 1)
})

test_that("6. should return -1 when the card is not found", {
  stack <- c(1, 3, 5)
  expect_equal(get_first_even_card_position(stack), -1)
})
